contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address account, uint256 id, uint256 n) public payable {
        require(account != address(0));

        c.createGameItem("test", "uri", true, true, 1_000_000, 0, 100); if (__ESBMC_reverted()) return;

        uint256 before = c.balanceOf(account, id); if (__ESBMC_reverted()) return;

        c.safeTransferFrom(address(0), account, id, n, ""); if (__ESBMC_reverted()) return;

        uint256 afterBalance = c.balanceOf(account, id); if (__ESBMC_reverted()) return;

        assert(afterBalance == before + n);
    }

    receive() external payable {}
}

