        c = new GameItems(address(this), address(this));
    }

    function _run(address account, uint256 id, uint256 n) internal {
        vm.assume(account != address(0));
        try c.createGameItem("test", "uri", true, true, 1_000_000, 0, 100) {} catch { return; }
        uint256 before;
        try c.balanceOf(account, id) returns (uint256 __r) { before = __r; } catch { return; }
        try c.safeTransferFrom(address(0), account, id, n, "") {} catch { return; }
        uint256 afterBalance;
        try c.balanceOf(account, id) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        assertTrue(afterBalance == before + n);
    }

